parameters.jsCode:
// One item per onboarding task that is due TODAY (Europe/Berlin).
// Due dates derive from the start date, so a moved start date simply
// moves the day the task is sent.
const cfg = $input.first().json;
const today = new Intl.DateTimeFormat('en-CA', { timeZone: 'Europe/Berlin' }).format(new Date());
const ownerRules = Object.fromEntries(
  String(cfg.ownerByTeam || '')
    .split(';')
    .map((r) => r.split('='))
    .filter((p) => p.length === 2)
);
const offsets = [
  ['management', cfg.mgmtDaysBefore, 'Prepare workstation access and intro plan'],
  ['department', cfg.deptDaysBefore, 'Inform the team and assign a buddy'],
  ['it', cfg.itDaysBefore, 'Create accounts and hardware requirements'],
  ['equipment', cfg.equipmentDaysBefore, 'Order equipment and work clothing'],
];
const tasks = [];
const reviewRows = [];
for (const item of $input.all()) {
  const r = item.json;
  const name = String(r.name || '').trim();
  const startDate = String(r.start_date || '').trim();
  const approved = String(r.status || '').toLowerCase() === 'approved';
  if (!approved) continue;
  if (!name || !/^\d{4}-\d{2}-\d{2}$/.test(startDate)) {
    reviewRows.push({ name: name || '(no name)', start_date: startDate || '(missing)', department: r.department || '' });
    continue;
  }
  const start = new Date(startDate + 'T00:00:00Z');
  for (const [team, daysBeforeRaw, description] of offsets) {
    const daysBefore = Number(daysBeforeRaw == null ? 0 : daysBeforeRaw);
    if (!daysBefore) continue;
    const due = new Date(start.getTime() - daysBefore * 86400000).toISOString().slice(0, 10);
    if (due !== today) continue;
    tasks.push({
      json: {
        hireName: name,
        department: String(r.department || ''),
        startDate,
        team,
        description,
        dueDate: due,
        ownerEmail: ownerRules[team] || String(cfg.hrInbox || ''),
        senderAddress: cfg.senderAddress,
        needsReview: false,
        reviewReason: '',
        reviewRows: [],
      },
    });
  }
}
if (reviewRows.length) {
  tasks.push({
    json: {
      needsReview: true,
      reviewReason: 'approved rows with missing name or start date',
      reviewRows,
      hireName: '',
      startDate: '',
      team: 'hr',
      description: '',
      dueDate: '',
      ownerEmail: String(cfg.hrInbox || ''),
      hrInbox: String(cfg.hrInbox || ''),
      senderAddress: cfg.senderAddress,
    },
  });
}
return tasks;

